/* Exact editorial translations for content rendered after page load. */
(() => {
  const normalise = text => text.replace(/\s+/g, ' ').trim();
  function translateText(raw) {
    const text = normalise(raw);
    let translated = translations[text];
    if (translated === undefined) {
      const decorated = text.match(/^(.*?)(\s*(?:↗|→|↑|↓|· LRIT))$/);
      if (decorated && translations[decorated[1].trim()] !== undefined) translated = translations[decorated[1].trim()] + ' ' + decorated[2].trim();
    }
    if (translated === undefined) {
      translated = text
        .replace(/^(\d{4}) · Doctorat$/, '$1 · PhD')
        .replace(/^(\d{4}) · HDR$/, '$1 · Research habilitation (HDR)')
        .replace(/^Page (\d+) sur (\d+)$/, 'Page $1 of $2')
        .replace(/^(\d[\d\s,.]*) références? trouvées? sur (\d[\d\s,.]*)$/, '$1 references found out of $2')
        .replace(/^(\d[\d\s,.]*) (?:notices?|manifestations?|membres?) affichées?s? sur (\d[\d\s,.]*)$/, '$1 records displayed out of $2')
        .replace(/^(\d+) visuels affichés sur (\d+)$/, '$1 images shown out of $2')
        .replace(/^(\d+) résultats?$/, '$1 results')
        .replace(/^(\d+) personnes?$/, (_,n) => n + (n === '1' ? ' person' : ' people'))
        .replace(/^(\d+) membres? sur (\d+)$/, '$1 members out of $2')
        .replace(/Défense nationale/g, 'National Defence')
        .replace(/^Portrait de /, 'Portrait of ')
        .replace(/^Document complémentaire : /, 'Supplementary document: ')
        .replace(/^Agrandir le document complémentaire /, 'Enlarge supplementary document ')
        .replace(/^Agrandir : /, 'Enlarge: ')
        .replace(/^Découvrir : /, 'Explore: ')
        .replace(/^DOMAINE DE RECHERCHE \/ /, 'RESEARCH AREA / ')
        .replace(/^LES SPÉCIALITÉS DU LRIT \/ /, 'LRIT SPECIALISMS / ')
        .replace(/^Inscription(?: en)? /, 'Enrolment ')
        .replace(/ · Encadrement /, ' · Supervision ')
        .replace(/^(.+) est (membre permanent|membre associé|doctorant) du LRIT(?:, avec une inscription en (.+))?\.$/, (_,name,status,year) => `${name} is a ${({'membre permanent':'permanent member','membre associé':'associate member','doctorant':'doctoral student'})[status]} of LRIT${year ? ', enrolled in ' + year : ''}.`);
    }
    if (translated === text && raw === text) return raw;
    if (translated === text) return raw;
    const leading = raw.match(/^\s*/)[0], trailing = raw.match(/\s*$/)[0];
    return leading + translated + trailing;
  }
  function originalText(node) {
    // Preserve official bibliographic titles and author names, not interface buttons.
    return node.parentElement?.closest('.reference-citation, .profile-publications h4, .profile-publications article > p');
  }
  function translateNode(node) {
    if (node.nodeType === Node.TEXT_NODE) {
      if (!node.parentElement || node.parentElement.closest('script,style,noscript,textarea') || originalText(node)) return;
      const next = translateText(node.nodeValue);
      if (next !== node.nodeValue) node.nodeValue = next;
    } else if (node.nodeType === Node.ELEMENT_NODE || node.nodeType === Node.DOCUMENT_NODE) {
      if (node.nodeType === Node.ELEMENT_NODE) {
        if (node.matches('script,style,textarea')) return;
        for (const attr of ['alt','title','placeholder','aria-label']) {
          if (node.hasAttribute(attr)) {
            const next = translateText(node.getAttribute(attr));
            if (next !== node.getAttribute(attr)) node.setAttribute(attr,next);
          }
        }
        if (node.matches('a[href]')) {
          const href = node.getAttribute('href');
          for (const origin of ['../master-it/en/index.html','https://lrit-rabat-recherche.singlebulb.chatgpt.site']) {
            if (origin.startsWith('https://') && (href === origin || href === origin + '/')) node.href = origin + '/en/';
          }
        }
      }
      for (const child of node.childNodes) translateNode(child);
    }
  }
  translateNode(document.documentElement);
  new MutationObserver(records => {
    for (const record of records) {
      if (record.type === 'characterData') translateNode(record.target);
      else if (record.type === 'attributes') translateNode(record.target);
      else for (const node of record.addedNodes) translateNode(node);
    }
  }).observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['alt','title','placeholder','aria-label']});
})();
